public class LocalDateTime_fromCalendarFields_TriageGen2Test {

    @Test
    public void testFromCalendarFields_NullCalendar() {
        try {
            LocalDateTime.fromCalendarFields(null);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("The calendar must not be null", e.getMessage());
        }
    }

    @Test
    public void testFromCalendarFields_GregorianAD() {
        Calendar calendar = new GregorianCalendar();
        calendar.set(2023, Calendar.OCTOBER, 25, 14, 30, 45);
        calendar.set(Calendar.MILLISECOND, 500);
        calendar.set(Calendar.ERA, GregorianCalendar.AD);

        LocalDateTime result = LocalDateTime.fromCalendarFields(calendar);

        assertEquals(2023, result.getYear());
        assertEquals(10, result.getMonthOfYear());
        assertEquals(25, result.getDayOfMonth());
        assertEquals(14, result.getHourOfDay());
        assertEquals(30, result.getMinuteOfHour());
        assertEquals(45, result.getSecondOfMinute());
        assertEquals(500, result.getMillisOfSecond());
    }

    @Test
    public void testFromCalendarFields_BC() {
        // Testing the branch: (era == GregorianCalendar.AD ? yearOfEra : 1 % yearOfEra)
        // Note: The implementation provided has a specific logic: 1 % yearOfEra
        // If era is BC, it returns 1 % yearOfEra.
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.ERA, GregorianCalendar.BC);
        calendar.set(Calendar.YEAR, 500);
        calendar.set(Calendar.MONTH, Calendar.JANUARY);
        calendar.set(Calendar.DAY_OF_MONTH, 1);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        LocalDateTime result = LocalDateTime.fromCalendarFields(calendar);

        // Based on code: (era == AD ? yearOfEra : 1 % yearOfEra)
        // Since era is BC, year should be 1 % 500 = 1
        assertEquals(1, result.getYear());
        assertEquals(1, result.getMonthOfYear());
        assertEquals(1, result.getDayOfMonth());
    }

    @Test
    public void testFromCalendarFields_BC_YearOne() {
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.ERA, GregorianCalendar.BC);
        calendar.set(Calendar.YEAR, 1);
        calendar.set(Calendar.MONTH, Calendar.DECEMBER);
        calendar.set(Calendar.DAY_OF_MONTH, 31);
        calendar.set(Calendar.HOUR_OF_DAY, 23);
        calendar.set(Calendar.MINUTE, 59);
        calendar.set(Calendar.SECOND, 59);
        calendar.set(Calendar.MILLISECOND, 999);

        LocalDateTime result = LocalDateTime.fromCalendarFields(calendar);

        // 1 % 1 = 0
        assertEquals(0, result.getYear());
        assertEquals(12, result.getMonthOfYear());
        assertEquals(31, result.getDayOfMonth());
        assertEquals(23, result.getHourOfDay());
        assertEquals(59, result.getMinuteOfHour());
        assertEquals(59, result.getSecondOfMinute());
        assertEquals(999, result.getMillisOfSecond());
    }
}
